namespace AppHotelAgenda13.Models;
public class Reserva { public string Nome { get; set; } = ""; public string Quarto { get; set; } = ""; public int Hospedes { get; set; } = 1; public DateTime Entrada { get; set; } = DateTime.Today; public DateTime Saida { get; set; } = DateTime.Today.AddDays(1); public int Diarias => (Saida - Entrada).Days; public decimal ValorDiaria => Quarto switch { "Suíte Premium" => 490m, "Quarto Família" => 370m, _ => 250m }; public decimal Total => Diarias * ValorDiaria; public string Periodo => $"{Entrada:dd/MM/yyyy} a {Saida:dd/MM/yyyy}"; public string TotalFormatado => Total.ToString("C", new System.Globalization.CultureInfo("pt-BR")); }
